// Minimum inspectors needed to cover n items with symmetric radius d.
// Each inspector covers at most (2*d + 1) consecutive items.
// Answer = ceil(n / (2*d + 1)).
fn min_inspectors(n: i8, d: i8) -> i8 {
    let n = n as i32;
    let d = d as i32;

    let cover = 2 * d + 1;          // items covered by one inspector
    let result = (n + cover - 1) / cover; // integer ceil division

    result as i8
}

